function createStars(){const t=document.getElementById("bgStars");for(let e=0;e<100;e++){const e=document.createElement("div");e.className="star",e.style.width=3*Math.random()+1+"px",e.style.height=e.style.width,e.style.left=100*Math.random()+"%",e.style.top=100*Math.random()+"%",e.style.animationDelay=3*Math.random()+"s",t.appendChild(e)}const e=["🎁","🎀","⭐","✨"];for(let n=0;n<8;n++){const n=document.createElement("div");n.className="floating-gift",n.textContent=e[Math.floor(Math.random()*e.length)],n.style.left=100*Math.random()+"%",n.style.top=100*Math.random()+"%",n.style.animationDelay=6*Math.random()+"s",t.appendChild(n)}}const openedBoxes=new Set(["1"]);function initGiftBoxes(){document.querySelectorAll(".gift-box").forEach(t=>{const e=t.dataset.box;"1"===e&&t.classList.add("opened"),t.addEventListener("click",()=>handleBoxClick(e))})}function handleBoxClick(t){openedBoxes.has(t)?window.location.href=`result.html?box=${t}`:openBox(t)}function openBox(t){const e=document.getElementById(`box${t}`);if(!e)return;openedBoxes.add(t),e.classList.add("opened");const n=e.querySelector(".gift-status");n&&(n.innerHTML="\n            <span>✅</span>\n            <span>Đã mở</span>\n        ",n.classList.remove("waiting")),createConfetti(),setTimeout(()=>{window.location.href=`result.html?box=${t}`},1500)}function createConfetti(){const t=["#fbbf24","#f59e0b","#ef4444","#ec4899","#8b5cf6","#3b82f6","#10b981"];for(let e=0;e<50;e++){const e=document.createElement("div");e.style.position="fixed",e.style.width=10*Math.random()+5+"px",e.style.height=e.style.width,e.style.backgroundColor=t[Math.floor(Math.random()*t.length)],e.style.left=100*Math.random()+"%",e.style.top="-20px",e.style.borderRadius=Math.random()>.5?"50%":"0",e.style.opacity="1",e.style.zIndex="9999",e.style.pointerEvents="none",document.body.appendChild(e);const n=2*Math.random()+2,o=200*(Math.random()-.5),a=720*Math.random();e.animate([{transform:"translate(0, 0) rotate(0deg)",opacity:1},{transform:`translate(${o}px, ${window.innerHeight+50}px) rotate(${a}deg)`,opacity:0}],{duration:1e3*n,easing:"cubic-bezier(0.25, 0.46, 0.45, 0.94)"}),setTimeout(()=>{e.remove()},1e3*n)}}function showNotification(t,e="info"){const n=document.createElement("div");n.style.cssText="\n        position: fixed;\n        top: 2rem;\n        right: 2rem;\n        background: white;\n        padding: 1rem 1.5rem;\n        border-radius: 12px;\n        box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);\n        z-index: 10000;\n        font-weight: 600;\n        color: #1f2937;\n        animation: slideIn 0.3s ease-out;\n    ";const o={success:"✅",error:"❌",info:"ℹ️",warning:"⚠️"};n.innerHTML=`\n        <span style="margin-right: 0.5rem;">${o[e]||o.info}</span>\n        <span>${t}</span>\n    `,document.body.appendChild(n),setTimeout(()=>{n.style.animation="slideOut 0.3s ease-in",setTimeout(()=>n.remove(),300)},3e3)}document.addEventListener("DOMContentLoaded",()=>{createStars(),initGiftBoxes()});const style=document.createElement("style");style.textContent="\n    @keyframes slideIn {\n        from {\n            transform: translateX(400px);\n            opacity: 0;\n        }\n        to {\n            transform: translateX(0);\n            opacity: 1;\n        }\n    }\n    \n    @keyframes slideOut {\n        from {\n            transform: translateX(0);\n            opacity: 1;\n        }\n        to {\n            transform: translateX(400px);\n            opacity: 0;\n        }\n    }\n",document.head.appendChild(style);